public sealed class CinematicPresentation:MonoBehaviour {
 public static void Configure(Camera camera){camera.GetUniversalAdditionalCameraData().renderPostProcessing=true;camera.GetUniversalAdditionalCameraData().antialiasing=AntialiasingMode.FastApproximateAntialiasing;camera.GetUniversalAdditionalCameraData().requiresDepthTexture=true;var pipeline=GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;if(pipeline!=null){pipeline.supportsCameraDepthTexture=true;pipeline.renderScale=1f;pipeline.msaaSampleCount=4;pipeline.shadowDistance=300;pipeline.maxAdditionalLightsCount=4;}
  RenderSettings.ambientLight=new Color(.22f,.27f,.34f);var key=GameObject.Find("Warm key").GetComponent<Light>();key.intensity=2.3f;key.color=new Color(1,.92f,.8f);key.shadows=LightShadows.Soft;key.transform.rotation=Quaternion.LookRotation(new Vector3(.25f,-.20f,.94f).normalized);var rim=GameObject.Find("Cool rim").GetComponent<Light>();rim.intensity=.65f;rim.color=new Color(.38f,.62f,1);
  var volume=new GameObject("Cinematic color / local procedural art").AddComponent<Volume>();volume.isGlobal=true;volume.profile=ScriptableObject.CreateInstance<VolumeProfile>();var bloom=volume.profile.Add<Bloom>();bloom.intensity.Override(.25f);bloom.threshold.Override(1.05f);bloom.scatter.Override(.65f);var tone=volume.profile.Add<Tonemapping>();tone.mode.Override(TonemappingMode.ACES);var color=volume.profile.Add<ColorAdjustments>();color.postExposure.Override(0f);color.contrast.Override(5);color.saturation.Override(-2);var vignette=volume.profile.Add<Vignette>();vignette.intensity.Override(.10f);vignette.smoothness.Override(.7f);var production=camera.gameObject.AddComponent<ProductionVisuals>();production.Initialize();
 }
 static Material Mat(Color color,float metal=.5f,float smooth=.6f,bool emissive=false){return ProductionMaterials.Create(color,metal,smooth,0,emissive?2:0,metal<.2f&&!emissive&&color.maxColorComponent>.2f);}
 static Transform Primitive(Transform parent,string name,PrimitiveType type,Vector3 position,Vector3 scale,Material material){var g=GameObject.CreatePrimitive(type);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=position;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=material;if(type==PrimitiveType.Cube)g.GetComponent<MeshFilter>().sharedMesh=ProductionGeometry.BeveledBox;Destroy(g.GetComponent<Collider>());return g.transform;}
 public static Transform Ship(out Transform exhaust){var root=new GameObject("PLAYER / Asterion survey interceptor").transform;
  Material armor=Mat(new Color(.34f,.40f,.46f),.65f,.58f),ceramic=Mat(new Color(.72f,.75f,.73f),.25f,.5f),carbon=Mat(new Color(.035f,.045f,.055f),.5f,.65f),copper=Mat(new Color(.42f,.15f,.055f),.75f,.65f),glass=Mat(new Color(.025f,.12f,.17f),.6f,.95f),light=Mat(new Color(.15f,.7f,1),.15f,.8f,true);
  var vertices=new List<Vector3>();var tris=new List<int>();float[] z={-1.6f,-.95f,.45f,1.65f},width={.5f,.78f,.55f,.07f},height={.31f,.43f,.28f,.08f};
  for(int ring=0;ring<4;ring++)for(int k=0;k<8;k++){float a=k*Mathf.PI/4;vertices.Add(new Vector3(Mathf.Cos(a)*width[ring],Mathf.Sin(a)*height[ring],z[ring]));}
  for(int r=0;r<3;r++)for(int k=0;k<8;k++){int a=r*8+k,b=r*8+(k+1)%8,c=(r+1)*8+k,d=(r+1)*8+(k+1)%8;tris.AddRange(new[]{a,b,c,b,d,c});}
  for(int k=1;k<7;k++)tris.AddRange(new[]{0,k+1,k});var mesh=new Mesh();mesh.SetVertices(vertices);mesh.SetTriangles(tris,0);mesh.RecalculateNormals();mesh.RecalculateBounds();var hull=new GameObject("Faceted pressure hull");hull.transform.SetParent(root,false);hull.AddComponent<MeshFilter>().sharedMesh=mesh;hull.AddComponent<MeshRenderer>().sharedMaterial=armor;
  Primitive(root,"Ceramic upper deck",PrimitiveType.Cube,new Vector3(0,.32f,-.18f),new Vector3(.8f,.12f,1.7f),ceramic);Primitive(root,"Canopy",PrimitiveType.Sphere,new Vector3(0,.36f,.37f),new Vector3(.65f,.34f,1.05f),glass);
  for(int side=-1;side<=1;side+=2){var wing=Primitive(root,"Swept radiator wing",PrimitiveType.Cube,new Vector3(side*.95f,-.08f,-.65f),new Vector3(1.5f,.1f,.72f),carbon);wing.localRotation=Quaternion.Euler(0,side*24,-side*5);Primitive(root,"Wing ceramic panel",PrimitiveType.Cube,new Vector3(side*.97f,.0f,-.6f),new Vector3(.9f,.045f,.35f),ceramic).localRotation=Quaternion.Euler(0,side*24,0);
   var engine=Primitive(root,"Engine nacelle",PrimitiveType.Cylinder,new Vector3(side*.67f,-.12f,-1.08f),new Vector3(.4f,.7f,.4f),carbon);engine.localRotation=Quaternion.Euler(90,0,0);var nozzle=Primitive(root,"Copper nozzle ring",PrimitiveType.Cylinder,new Vector3(side*.67f,-.12f,-1.73f),new Vector3(.43f,.09f,.43f),copper);nozzle.localRotation=Quaternion.Euler(90,0,0);
   Primitive(root,"Navigation strip",PrimitiveType.Cube,new Vector3(side*.49f,.2f,.45f),new Vector3(.035f,.035f,.65f),light);for(int j=0;j<5;j++)Primitive(root,"Heat vent",PrimitiveType.Cube,new Vector3(side*.43f,.24f,-1+j*.16f),new Vector3(.24f,.04f,.065f),carbon);
  }
  var gear=new GameObject("Landing gear").transform;gear.SetParent(root,false);Vector3[] feet={new Vector3(-.5f,-.46f,-.8f),new Vector3(.5f,-.46f,-.8f),new Vector3(0,-.46f,.85f)};foreach(var p in feet){Primitive(gear,"Landing strut",PrimitiveType.Cylinder,p,new Vector3(.055f,.10f,.055f),carbon);Primitive(gear,"Landing pad",PrimitiveType.Cube,p+Vector3.down*.12f,new Vector3(.24f,.04f,.28f),copper);}gear.gameObject.SetActive(false);
  exhaust=new GameObject("Variable dual exhaust assembly").transform;exhaust.SetParent(root,false);exhaust.localPosition=new Vector3(0,0,-1.85f);var glow=new Material(Shader.Find("Orbit/Glow"));glow.SetColor("_Color",new Color(.12f,.6f,1,.85f)*2);
  for(int side=-1;side<=1;side+=2){var jet=new GameObject("Plasma exhaust");jet.transform.SetParent(exhaust,false);jet.transform.localPosition=new Vector3(side*.67f,-.12f,0);jet.AddComponent<MeshFilter>().sharedMesh=ExhaustMesh();jet.AddComponent<MeshRenderer>().sharedMaterial=new Material(Shader.Find("Orbit/Exhaust"));}
  for(int side=-1;side<=1;side+=2){var lamp=new GameObject("Landing floodlight");lamp.transform.SetParent(root,false);lamp.transform.localPosition=new Vector3(side*.55f,-.1f,.9f);lamp.transform.localRotation=Quaternion.Euler(32,0,0);var l=lamp.AddComponent<Light>();l.type=LightType.Spot;l.range=85;l.spotAngle=70;l.innerSpotAngle=40;l.intensity=450;l.color=new Color(.74f,.85f,1);l.enabled=false;}
  return root;
 }
 static Mesh ExhaustMesh(){var v=new List<Vector3>();var uv=new List<Vector2>();var tr=new List<int>();int n=16;for(int ring=0;ring<7;ring++){float t=ring/6f;for(int i=0;i<=n;i++){float a=i*Mathf.PI*2/n,r=Mathf.Lerp(1,.04f,t)*(1+.06f*Mathf.Sin(a*5+ring));v.Add(new Vector3(Mathf.Cos(a)*r,Mathf.Sin(a)*r,-t));uv.Add(new Vector2((float)i/n,t));if(ring<6&&i<n){int k=ring*(n+1)+i;tr.AddRange(new[]{k,k+1,k+n+1,k+1,k+n+2,k+n+1});}}}var mesh=new Mesh();mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetTriangles(tr,0);mesh.RecalculateBounds();return mesh;}
 public static void Engine(Transform exhaust,float power,bool active){exhaust.gameObject.SetActive(active);if(!active)return;foreach(Transform p in exhaust){p.localScale=new Vector3(.22f,.22f,.45f+power*.13f);p.localPosition=new Vector3(p.localPosition.x,-.12f,0);}}
 public static void DetailAstronaut(Transform root){Material dark=Mat(new Color(.055f,.075f,.085f),.1f,.25f),armor=Mat(new Color(.42f,.48f,.48f),.45f,.35f),cloth=Mat(new Color(.58f,.63f,.61f),.05f,.2f),lamp=Mat(new Color(.2f,.65f,1),.1f,.5f,true);Primitive(root,"Chest life-support panel",PrimitiveType.Cube,new Vector3(0,.14f,-.23f),new Vector3(.32f,.28f,.11f),dark);Primitive(root,"Chest display",PrimitiveType.Cube,new Vector3(0,.18f,-.292f),new Vector3(.19f,.08f,.012f),lamp);Primitive(root,"Suit belt",PrimitiveType.Cube,new Vector3(0,-.23f,0),new Vector3(.53f,.095f,.4f),dark);for(int side=-1;side<=1;side+=2){Primitive(root,"Shoulder armor",PrimitiveType.Sphere,new Vector3(side*.37f,.27f,0),new Vector3(.25f,.21f,.29f),armor);Primitive(root,"Knee armor",PrimitiveType.Cube,new Vector3(side*.18f,-.57f,-.12f),new Vector3(.19f,.13f,.09f),armor);Primitive(root,"Boot sole",PrimitiveType.Cube,new Vector3(side*.18f,-.84f,-.02f),new Vector3(.25f,.09f,.31f),dark);Primitive(root,"Backpack canister",PrimitiveType.Cylinder,new Vector3(side*.27f,-.03f,.25f),new Vector3(.13f,.3f,.13f),cloth);Primitive(root,"Harness",PrimitiveType.Cube,new Vector3(side*.21f,.1f,-.2f),new Vector3(.045f,.49f,.065f),dark);}Primitive(root,"Helmet lamp",PrimitiveType.Cube,new Vector3(.25f,.72f,-.20f),new Vector3(.08f,.065f,.12f),lamp);Primitive(root,"Pack antenna",PrimitiveType.Cylinder,new Vector3(.23f,.5f,.25f),new Vector3(.017f,.35f,.017f),dark);
  var torso=root.Find("Pressure suit");if(torso!=null)torso.GetComponent<Renderer>().sharedMaterial=ProductionMaterials.Create(new Color(.38f,.43f,.45f),.05f,.24f,0,0,true);
  var helmet=root.Find("Helmet");if(helmet!=null)helmet.GetComponent<Renderer>().sharedMaterial=armor;
  var visor=root.Find("Gold visor");if(visor!=null){var visorMaterial=ProductionMaterials.Create(new Color(.16f,.075f,.02f),.7f,.92f);visorMaterial.SetFloat("_ClearCoat",1);visorMaterial.SetFloat("_NormalStrength",.01f);visor.GetComponent<Renderer>().sharedMaterial=visorMaterial;}
  var pack=root.Find("Backpack");if(pack!=null)pack.gameObject.SetActive(false);
  Primitive(root,"Life-support chassis",PrimitiveType.Cube,new Vector3(0,-.02f,.27f),new Vector3(.46f,.58f,.26f),armor);
  Primitive(root,"Replaceable power cell",PrimitiveType.Cube,new Vector3(0,-.06f,.42f),new Vector3(.32f,.38f,.055f),dark);
  Primitive(root,"Backpack status display",PrimitiveType.Cube,new Vector3(0,.16f,.432f),new Vector3(.2f,.055f,.025f),lamp);
  Material orange=Mat(new Color(.75f,.19f,.035f),.15f,.35f);
  for(int j=0;j<5;j++)Primitive(root,"Pack heat exchanger",PrimitiveType.Cube,new Vector3(0,-.2f+j*.062f,.46f),new Vector3(.22f,.022f,.025f),armor);
  for(int side=-1;side<=1;side+=2){Primitive(root,"Suit safety stripe",PrimitiveType.Cube,new Vector3(side*.24f,.12f,.41f),new Vector3(.03f,.38f,.04f),orange);Primitive(root,"Helmet rim segment",PrimitiveType.Cube,new Vector3(side*.22f,.37f,.22f),new Vector3(.12f,.06f,.08f),dark);}
 }
 static int activeBursts;
 public static void Impact(Vector3 p,Color color){if(VoyagerAudio.Current!=null)VoyagerAudio.Current.Cue("impact",p);if(VoyagerVfx.Current!=null){VoyagerVfx.Current.Impact(p,color);return;}if(activeBursts>=16)return;activeBursts++;var g=new GameObject("Transient impact / bounded lifetime");g.transform.position=p;g.AddComponent<CinematicPresentation>().StartCoroutine(Burst(g,color));}
 static IEnumerator Burst(GameObject root,Color color){var lines=new LineRenderer[10];for(int i=0;i<lines.Length;i++){var l=new GameObject("Impact spark").AddComponent<LineRenderer>();l.transform.SetParent(root.transform,false);l.useWorldSpace=false;l.positionCount=2;l.material=new Material(Shader.Find("Orbit/Glow"));l.material.SetColor("_Color",color*2);l.widthMultiplier=.045f;Vector3 d=Random.onUnitSphere;l.SetPositions(new[]{d*.15f,d*(.4f+Random.value*.6f)});lines[i]=l;}float age=0;while(age<.55f){age+=Time.deltaTime;root.transform.localScale=Vector3.one*(1+age*5);foreach(var l in lines)l.widthMultiplier=.045f*(1-age/.55f);yield return null;}foreach(var l in lines)Destroy(l.material);Destroy(root);activeBursts--;}
}
